SELECT ?chart ?chartLabelEn ?chartLabelRu ?performer ?performerLabelEn ?performerLabelRu ?label ?labelLabelEn ?labelLabelRu ?peak_rank_max ?period_start ?gold_count_estimate WHERE {
      {
        SELECT ?chart ?chartLabelEn ?chartLabelRu ?performer ?performerLabelEn ?performerLabelRu ?label ?labelLabelEn ?labelLabelRu ?peak_rank_max ?period_start (COUNT(DISTINCT ?item) AS ?gold_count_estimate) WHERE {
        ?item wdt:P31 wd:Q134556 .
        ?item wdt:P577 ?date .
        BIND(YEAR(?date) AS ?year) .
        FILTER(?year >= 1950 && ?year <= 2025) .
        ?item p:P2291 ?chartStatement .
        ?chartStatement ps:P2291 ?chart .
        ?chartStatement pq:P1352 ?peakRank .
        FILTER(xsd:decimal(?peakRank) <= 20) .
        BIND(20 AS ?peak_rank_max) .
        ?item wdt:P175 ?performer .
        ?item wdt:P264 ?label .
        ?chart rdfs:label ?chartLabelEn FILTER(LANG(?chartLabelEn) = "en") .
        OPTIONAL { ?chart rdfs:label ?chartLabelRu FILTER(LANG(?chartLabelRu) = "ru") . }
        ?performer rdfs:label ?performerLabelEn FILTER(LANG(?performerLabelEn) = "en") .
        OPTIONAL { ?performer rdfs:label ?performerLabelRu FILTER(LANG(?performerLabelRu) = "ru") . }
        ?label rdfs:label ?labelLabelEn FILTER(LANG(?labelLabelEn) = "en") .
        OPTIONAL { ?label rdfs:label ?labelLabelRu FILTER(LANG(?labelLabelRu) = "ru") . }
        BIND((FLOOR((?year - 1950) / 20) * 20 + 1950) AS ?period_start) .
        }
        GROUP BY ?chart ?chartLabelEn ?chartLabelRu ?performer ?performerLabelEn ?performerLabelRu ?label ?labelLabelEn ?labelLabelRu ?peak_rank_max ?period_start
      }
      FILTER(?gold_count_estimate >= 5 && ?gold_count_estimate <= 180)
    }
    ORDER BY DESC(?gold_count_estimate)
    LIMIT 800

